1	@import "tailwindcss";
2	
3	/* Runtime values (--theme-* and --color-*) are injected at :root by app/app.vue
4	   from runtimeConfig.public.theme; these tokens expose them as utilities. */
5	@theme inline {
6	  --color-primary: var(--theme-primary);
7	  --color-secondary: var(--theme-secondary);
8	  --color-background: var(--theme-background);
9	}
10	
11	html {
12	  color-scheme: light;
13	}
14	
15	html[data-theme="dark"] {
16	  color-scheme: dark;
17	}
18	
19	@media (prefers-color-scheme: dark) {
20	  html:not([data-theme="light"]) {
21	    color-scheme: dark;
22	  }
23	}
24	
25	body {
26	  background-color: var(--theme-background);
27	  color: var(--theme-secondary);
28	}
29

1	/** Cookie-backed theme mode; readable on server and client, so SSR output matches hydration. */
2	export function useThemeMode() {
3	  const cookie = useCookie<string>('theme-mode', {
4	    default: () => 'system',
5	    sameSite: 'lax',
6	    maxAge: 60 * 60 * 24 * 365,
7	  })
8	  const mode = computed<ThemeMode>({
9	    get: () => (isThemeMode(cookie.value) ? cookie.value : 'system'),
10	    set: (value) => {
11	      cookie.value = value
12	    },
13	  })
14	  return mode
15	}
16

1	export interface ThemeConfig {
2	  lightPrimary: string
3	  lightSecondary: string
4	  lightBackground: string
5	  darkPrimary: string
6	  darkSecondary: string
7	  darkBackground: string
8	}
9	
10	export type ThemeMode = 'light' | 'dark' | 'system'
11	
12	export const DEFAULT_THEME: Readonly<ThemeConfig> = {
13	  lightPrimary: '#32a9e1',
14	  lightSecondary: '#1e40af',
15	  lightBackground: '#ffffff',
16	  darkPrimary: '#7dd3fc',
17	  darkSecondary: '#94a3b8',
18	  darkBackground: '#020617',
19	}
20	
21	const HEX_RE = /^#(?:[0-9a-f]{3}|[0-9a-f]{6})$/i
22	
23	export function isValidHex(value: unknown): value is string {
24	  return typeof value === 'string' && HEX_RE.test(value.trim())
25	}
26	
27	/** Returns a lower-cased valid hex colour, or the fallback when malformed. */
28	export function sanitizeHex(value: unknown, fallback: string): string {
29	  return isValidHex(value) ? value.trim().toLowerCase() : fallback
30	}
31	
32	export function resolveTheme(input?: Partial<Record<keyof ThemeConfig, unknown>> | null): ThemeConfig {
33	  const source = input ?? {}
34	  const out = { ...DEFAULT_THEME }
35	  for (const key of Object.keys(DEFAULT_THEME) as (keyof ThemeConfig)[]) {
36	    out[key] = sanitizeHex(source[key], DEFAULT_THEME[key])
37	  }
38	  return out
39	}
40	
41	export function isThemeMode(value: unknown): value is ThemeMode {
42	  return value === 'light' || value === 'dark' || value === 'system'
43	}
44	
45	/** Builds the :root CSS for light, prefers-color-scheme dark, and data-theme overrides. */
46	export function buildThemeCss(input?: Partial<Record<keyof ThemeConfig, unknown>> | null): string {
47	  const t = resolveTheme(input)
48	  // --theme-* feed the Tailwind @theme tokens (a token cannot reference its own name);
49	  // --color-* carry the same values for direct use.
50	  const vars = (p: string, s: string, b: string) =>
51	    `--theme-primary:${p};--theme-secondary:${s};--theme-background:${b};--color-primary:${p};--color-secondary:${s};--color-background:${b};`
52	  const light = vars(t.lightPrimary, t.lightSecondary, t.lightBackground)
53	  const dark = vars(t.darkPrimary, t.darkSecondary, t.darkBackground)
54	  return [
55	    `:root{${light}}`,
56	    `@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){${dark}}}`,
57	    `:root[data-theme="light"]{${light}}`,
58	    `:root[data-theme="dark"]{${dark}}`,
59	  ].join('\n')
60	}
