1	import type { NitroFetchOptions, NitroFetchRequest } from 'nitropack'
2	
3	/**
4	 * `$fetch` wrapper for authenticated API calls: adds the Bearer header and signs the user out
5	 * (clearing the cookie and redirecting to /login) when the API answers 401.
6	 */
7	export function useApi() {
8	  const { apiBase, getToken, clearSession, withContext, expiredNotice } = useAuth()
9	
10	  return async function api<T>(path: string, options: NitroFetchOptions<NitroFetchRequest> = {}): Promise<T> {
11	    const token = getToken()
12	    try {
13	      return await $fetch<T>(path, {
14	        ...options,
15	        baseURL: apiBase(),
16	        headers: { ...(options.headers as Record<string, string> | undefined), ...(token ? { Authorization: `Bearer ${token}` } : {}) },
17	      }) as T
